fn refresh_runtime_ledgers(&mut self) {
    if self.env_overlay.is_empty() {
        for (key, value) in self.env_vars.iter() {
            self.env_overlay.insert(key.clone(), value.clone());
        }
    }
    if self.env_path_entries.is_empty() {
        if let Some(path) = self.env_overlay.get("PATH").cloned().or_else(|| self.env_overlay.get("Path").cloned()) {
            self.lookup_path_blob = path.clone();
            self.env_path_entries = if cfg!(windows) {
                path.split(';').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()
            } else {
                path.split(':').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()
            };
        }
    }
    if self.lookup_cwd.is_empty() {
        if let Some(pwd) = self.env_overlay.get("PWD").cloned() {
            self.lookup_cwd = pwd.clone();
            self.cwd_real = pwd;
        }
    }
    if self.arg_scratch.is_empty() {
        self.arg_scratch = self.args.iter().map(|a| a.item.clone()).collect();
    }
    self.refresh_env_ledger();
    self.refresh_lookup_ledger();
    self.refresh_capture_ledger();
    self.refresh_stdio_ledger();
    self.refresh_arg_ledger();
    self.refresh_cwd_ledger();
    self.refresh_spawn_ledger();
}

